```

## 6. Handle Command Execution

Let's handle the execution of the `ban` command:

Create a new file inside your `src/commands` called `ban.cmd.ts`. 

Firstly, import necessary modules and interfaces:

```TypeScript
import { ArgsOf, CommandInteraction, InteractionReplyOptions } from 'discord.js';
import { Command, PieceContext } from '@jiman324/discord-cli';
import { isMessageAuthorAdmin } from '../utils/permissions';
```

Next, create your command definition:

```TypeScript
export class BanCommand extends Command {
    constructor() {
        super({
            name: 'ban',
            description: 'Bans a user from the server.',
            type: 'CHAT_INPUT',
            options: [
                {
                    name: 'users',
                    type: 'USER',
                    required: true,
                    description: 'The user to ban.',
                },
                {
                    name:'reason',
                    type: 'STRING',
                    description: 'The reason for banning the user.',
                    required: false,
                },
            ],
            permissions: ["ADMINISTRATOR"],
        })
    }

    async execute(intr: CommandInteraction<PieceContext>, _: ArgsOf<typeof this>) {
        const targetMember = intr.options.getMember/User('users');
        const reason = intr.options.getString('reason', true);

        // Check if author has sufficient permissions
        if (!isMessageAuthorAdmin(intr.member)) return intr.reply({
            content: 'You do not have permission to perform this action.',
            ephemeral: true,
        });

        await intr.guild?.members.ban(targetMember, { days: 7, reason: reason || 'No reason supplied' }); 
        return intr.reply({
            content: `${targetMember.user.tag} has been banned for ${reason? `**${reason}**` : ''}. `,
            ephemeral: true,
        });
    }
}
```

That's it! You're now good to go. Restart the Discorb Bot's server and test your newly added command!

